namespace
{
    void wd(const char* fmt, ...)
    {
        char buf[512];
        va_list ap;
        va_start(ap, fmt);
        vsnprintf(buf, sizeof(buf), fmt, ap);
        va_end(ap);
        watchdog_append(buf);
    }

    // 1.0.43 (i) inlined_array skip counter (exported via d3d12_rsx_inlined_skips()).
    static std::atomic<unsigned long long> s_inlined_skips{0};
    // 1.0.43 (ii) un-sampled unique VP tracker: fixed 32-entry table, zero spam
    // beyond it. True = newly inserted (and logged); false = seen, or table full.
    bool vp_track(u64 hash, int draw_mode)
    {
        static u64 seen[32];
        static unsigned seen_count = 0;
        for (unsigned i = 0; i < seen_count; ++i)
            if (seen[i] == hash) return false;
        if (seen_count >= 32) return false;
        const unsigned idx = seen_count++;
        seen[idx] = hash;
        wd("[VP-NEW] idx=%u hash=0x%016llX draw_mode=%d\r\n", idx, (unsigned long long)hash, draw_mode);
        return true;
    }
    inline u32 bswap32(u32 v) { return _byteswap_ulong(v); }
    inline u16 bswap16(u16 v) { return _byteswap_ushort(v); }

    inline void barrier(ID3D12GraphicsCommandList* list, ID3D12Resource* res,
                        D3D12_RESOURCE_STATES before, D3D12_RESOURCE_STATES after)
    {
        if (before == after)
            return;
        D3D12_RESOURCE_BARRIER b{};
        b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        b.Transition.pResource = res;
        b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
        b.Transition.StateBefore = before;
        b.Transition.StateAfter = after;
        list->ResourceBarrier(1, &b);
    }

    // Primitive class -> (D3D12 topology, PSO topology type). Fan, quads,
    // quad_strip and polygon are approximated as triangle lists (named
    // Slice 2 limitation: visible but wrong shape).
    struct TopoMap
    {
        D3D12_PRIMITIVE_TOPOLOGY topo;
        D3D12_PRIMITIVE_TOPOLOGY_TYPE type;
        bool approx;
    };
    TopoMap map_topo(rsx::primitive_type p)
    {
        using pt = rsx::primitive_type;
        switch (p)
        {
        case pt::triangles: return {D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, false};
        case pt::triangle_strip: return {D3D_PRIMITIVE_TOPOLOGY_TRIANGLESTRIP, D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, false};
        case pt::triangle_fan: return {D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, true};
        case pt::lines: return {D3D_PRIMITIVE_TOPOLOGY_LINELIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE, false};
        case pt::line_loop: return {D3D_PRIMITIVE_TOPOLOGY_LINESTRIP, D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE, true};
        case pt::line_strip: return {D3D_PRIMITIVE_TOPOLOGY_LINESTRIP, D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE, false};
        case pt::points: return {D3D_PRIMITIVE_TOPOLOGY_POINTLIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_POINT, false};
        case pt::quads:
        case pt::quad_strip:
        case pt::polygon: return {D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, true};
        default: return {D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST, D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, true};
        }
    }
} // namespace

