bool D3D12GSRender::miss_at(u64 ordinal, u64* vp, u64* fp)
{
    const u64 total = s_miss_next.load();
    if (ordinal >= total || !vp || !fp)
        return false;
    // Ring holds the LAST 64 misses; ordinals older than total-64
    // have been overwritten (host logs an overflow line in that case).
    if (total - ordinal > kMissRingSize)
        return false;
    const auto& p = s_miss_ring[ordinal % kMissRingSize];
    *vp = p.first;
    *fp = p.second;
    return true;
}

const std::string& D3D12GSRender::cache_path()
{
    return s_cache_path;
}

void D3D12GSRender::load_shader_cache()
{
    s_cache_pairs.clear();
    s_cache_entries.store(0);
    if (s_cache_dir.empty())
    {
        s_cache_path.clear();
        return;
    }
    std::string path = s_cache_dir;
    if (!path.empty() && path.back() != '/' && path.back() != '\\')
        path += '/';
    path += "d3d12_shader_cache.bin";
    s_cache_path = path;

    std::ifstream in(path, std::ios::binary);
    if (!in)
        return; // Missing file is the expected first-run state (all misses).

    char magic[8] = {};
    u32 version = 0, count = 0;
    in.read(magic, 8);
    in.read(reinterpret_cast<char*>(&version), sizeof(version));
    in.read(reinterpret_cast<char*>(&count), sizeof(count));
    if (!in || std::string(magic, 8) != "D3D12SC1" || version != 1 || count > 1000000u)
    {
        // Corrupt/unexpected header: treat as empty, do not crash the
        // RSX thread over a cache file. The host logs entries=0.
        s_cache_pairs.clear();
        s_cache_entries.store(0);
        return;
    }
    for (u32 i = 0; i < count; ++i)
    {
        u64 vp = 0, fp = 0;
        u32 blob_size = 0;
        in.read(reinterpret_cast<char*>(&vp), sizeof(vp));
        in.read(reinterpret_cast<char*>(&fp), sizeof(fp));
        in.read(reinterpret_cast<char*>(&blob_size), sizeof(blob_size));
        if (!in || blob_size > (64u << 20))
            break;
        // Blob bytes are skipped: 1.0.30 recognises HITs but does not
        // yet create PSOs from blobs (see header — device handoff
        // is the named next step).
        in.seekg(blob_size, std::ios::cur);
        if (!in)
            break;
        s_cache_pairs.emplace(vp, fp);
    }
    s_cache_entries.store(s_cache_pairs.size());
}

bool D3D12GSRender::cache_lookup(u64 vp_hash, u64 fp_hash) const
{
    return s_cache_pairs.find(std::make_pair(vp_hash, fp_hash)) != s_cache_pairs.end();
}

void D3D12GSRender::on_init_thread()
{
    s_init_count.fetch_add(1);
    {
            char wbuf[256];
            std::snprintf(wbuf, sizeof(wbuf), "BOOT-RSX-THREAD-START ms=%lld init=%llu (RSX thread entered on_init_thread; ms=-1 means during Load, before boot-return)\r\n", watchdog_ms_since_boot(), (unsigned long long)s_init_count.load());
            watchdog_append(wbuf);
        }
    load_shader_cache();
    // GSRender base: guards the null frame, sets up the context only
    // when a frame exists. With get_gs_frame() == nullptr this is a
    // no-op beyond the count — that is the intended behaviour here:
    // the RSX thread runs headless until a real frame path exists.
    GSRender::on_init_thread();
}

void D3D12GSRender::begin()
{
    s_begin_count.fetch_add(1);
    // Base thread seam only (conditional-render + draw-mode
    // bookkeeping, RSXThread.cpp thread::begin).
    rsx::thread::begin();
    // 1.0.36 Slice 2: bind the persistent scratch RTV for this frame's
    // draws (no-op when the bridge is absent — nop fallback preserved).
    slice_begin_frame();
}

// ---- Slice 1+2 implementation ----

void D3D12GSRender::slice_note_skip(SkipReason r)
{
    s_real_skips.fetch_add(1);
    s_skip_reasons[r].fetch_add(1);
    if (!m_skip_logged[r])
    {
        m_skip_logged[r] = true;
        static const char* names[kSkipCount] = {
            "layout-invalid", "immediate-draw", "no-pos-attr", "pos-type",
            "pos-offset", "upload-overflow", "guest-unmapped", "single-vertex",
            "empty-clause", "inlined-array", "no-draw-command",
        };
        wd("BOOT-DRAW-SKIP reason=%s total_skips=%llu\r\n",
           names[r], (unsigned long long)s_real_skips.load());
    }
}

bool D3D12GSRender::slice_ensure_resources()
{
    if (m_slice_ok)
        return true;
    ID3D12Device* dev = s_bridge.device;
    if (!dev)
        return false;

    auto fail = [&](const char* what, HRESULT hr)
    {
        if (!m_slice_pso_logged)
        {
            m_slice_pso_logged = true;
            wd("BOOT-SLICE-PSO-FAIL what=%s hr=0x%08lX (RSX flip stays count-only; host keeps presenting)\r\n",
               what, (unsigned long)hr);
        }
        return false;
    };

    HRESULT hr = S_OK;
    const UINT W = s_bridge.width ? s_bridge.width : 1280;
    const UINT H = s_bridge.height ? s_bridge.height : 720;

    // Command allocator + list (DIRECT).
    if (!m_slice_alloc)
    {
        hr = dev->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT, IID_PPV_ARGS(&m_slice_alloc));
        if (FAILED(hr)) return fail("alloc", hr);
    }
    if (!m_slice_list)
    {
        hr = dev->CreateCommandList(0, D3D12_COMMAND_LIST_TYPE_DIRECT, m_slice_alloc.Get(), nullptr, IID_PPV_ARGS(&m_slice_list));
        if (FAILED(hr)) return fail("list", hr);
        m_slice_list->Close(); // start closed; begin() resets per frame
    }

    // Root signatures (versioned 1.0, FL11_0-safe).
    if (!m_slice_rs)
    {
        D3D12_VERSIONED_ROOT_SIGNATURE_DESC rs{};
        rs.Version = D3D_ROOT_SIGNATURE_VERSION_1_0;
        rs.Desc_1_0.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
        Microsoft::WRL::ComPtr<ID3DBlob> blob, err;
        hr = D3D12SerializeVersionedRootSignature(&rs, &blob, &err);
        if (FAILED(hr)) return fail("slice-rs-serialize", hr);
        hr = dev->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(), IID_PPV_ARGS(&m_slice_rs));
        if (FAILED(hr)) return fail("slice-rs", hr);
    }
    if (!m_blit_rs)
    {
        D3D12_DESCRIPTOR_RANGE range{};
        range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        range.NumDescriptors = 1;
        range.BaseShaderRegister = 0;
        range.RegisterSpace = 0;
        range.OffsetInDescriptorsFromTableStart = 0;
        D3D12_ROOT_PARAMETER param{};
        param.ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        param.DescriptorTable.NumDescriptorRanges = 1;
        param.DescriptorTable.pDescriptorRanges = &range;
        param.ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
        D3D12_STATIC_SAMPLER_DESC samp{};
        samp.Filter = D3D12_FILTER_MIN_MAG_MIP_POINT;
        samp.AddressU = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        samp.AddressV = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        samp.AddressW = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        samp.ShaderRegister = 0;
        samp.RegisterSpace = 0;
        samp.ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
        D3D12_VERSIONED_ROOT_SIGNATURE_DESC rs{};
        rs.Version = D3D_ROOT_SIGNATURE_VERSION_1_0;
        rs.Desc_1_0.NumParameters = 1;
        rs.Desc_1_0.pParameters = &param;
        rs.Desc_1_0.NumStaticSamplers = 1;
        rs.Desc_1_0.pStaticSamplers = &samp;
        rs.Desc_1_0.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
        Microsoft::WRL::ComPtr<ID3DBlob> blob, err;
        hr = D3D12SerializeVersionedRootSignature(&rs, &blob, &err);
        if (FAILED(hr)) return fail("blit-rs-serialize", hr);
        hr = dev->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(), IID_PPV_ARGS(&m_blit_rs));
        if (FAILED(hr)) return fail("blit-rs", hr);
    }

    // PSOs (build-time dxc blobs from slice_shaders.h — no runtime compiler).
    if (!m_slice_pso_tri || !m_slice_pso_line || !m_slice_pso_point)
    {
        D3D12_INPUT_ELEMENT_DESC layout[] = {
            {"POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 0, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0},
        };
        D3D12_GRAPHICS_PIPELINE_STATE_DESC pso{};
        pso.pRootSignature = m_slice_rs.Get();
        pso.VS.pShaderBytecode = slice_vs_cso;
        pso.VS.BytecodeLength = slice_vs_cso_len;
        pso.PS.pShaderBytecode = slice_ps_cso;
        pso.PS.BytecodeLength = slice_ps_cso_len;
        pso.BlendState.RenderTarget[0].RenderTargetWriteMask = D3D12_COLOR_WRITE_ENABLE_ALL;
        pso.SampleMask = UINT_MAX;
        pso.RasterizerState.FillMode = D3D12_FILL_MODE_SOLID;
        pso.RasterizerState.CullMode = D3D12_CULL_MODE_NONE;
        pso.DepthStencilState.DepthEnable = FALSE;
        pso.InputLayout.pInputElementDescs = layout;
        pso.InputLayout.NumElements = 1;
        pso.SampleDesc.Count = 1;
        pso.NumRenderTargets = 1;
        pso.RTVFormats[0] = DXGI_FORMAT_R8G8B8A8_UNORM;
        pso.DSVFormat = DXGI_FORMAT_UNKNOWN;
        const struct { D3D12_PRIMITIVE_TOPOLOGY_TYPE t; Microsoft::WRL::ComPtr<ID3D12PipelineState>* out; const char* n; }
        variants[] = {
            {D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE, &m_slice_pso_tri, "slice-pso-tri"},
            {D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE, &m_slice_pso_line, "slice-pso-line"},
            {D3D12_PRIMITIVE_TOPOLOGY_TYPE_POINT, &m_slice_pso_point, "slice-pso-point"},
        };
        for (const auto& v : variants)
        {
            if (*v.out)
                continue;
            pso.PrimitiveTopologyType = v.t;
            hr = dev->CreateGraphicsPipelineState(&pso, IID_PPV_ARGS(v.out->GetAddressOf()));
            if (FAILED(hr)) return fail(v.n, hr);
        }
    }
    if (!m_blit_pso)
    {
        D3D12_GRAPHICS_PIPELINE_STATE_DESC pso{};
        pso.pRootSignature = m_blit_rs.Get();
        pso.VS.pShaderBytecode = blit_vs_cso;
        pso.VS.BytecodeLength = blit_vs_cso_len;
        pso.PS.pShaderBytecode = blit_ps_cso;
        pso.PS.BytecodeLength = blit_ps_cso_len;
        pso.BlendState.RenderTarget[0].RenderTargetWriteMask = D3D12_COLOR_WRITE_ENABLE_ALL;
        pso.SampleMask = UINT_MAX;
        pso.RasterizerState.FillMode = D3D12_FILL_MODE_SOLID;
        pso.RasterizerState.CullMode = D3D12_CULL_MODE_NONE;
        pso.DepthStencilState.DepthEnable = FALSE;
        pso.SampleDesc.Count = 1;
        pso.PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;
        pso.NumRenderTargets = 1;
        pso.RTVFormats[0] = DXGI_FORMAT_R8G8B8A8_UNORM;
        pso.DSVFormat = DXGI_FORMAT_UNKNOWN;
        hr = dev->CreateGraphicsPipelineState(&pso, IID_PPV_ARGS(&m_blit_pso));
        if (FAILED(hr)) return fail("blit-pso", hr);
    }

    // Heaps + textures + upload rings.
    if (!m_rtv_heap)
    {
        D3D12_DESCRIPTOR_HEAP_DESC h{};
        h.Type = D3D12_DESCRIPTOR_HEAP_TYPE_RTV;
        h.NumDescriptors = 3; // scratch + 2 swapchain backbuffers
        h.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_NONE;
        hr = dev->CreateDescriptorHeap(&h, IID_PPV_ARGS(&m_rtv_heap));
        if (FAILED(hr)) return fail("rtv-heap", hr);
    }
    if (!m_srv_heap)
    {
        D3D12_DESCRIPTOR_HEAP_DESC h{};
        h.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
        h.NumDescriptors = 2; // display(swizzle) + scratch(identity)
        h.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
        hr = dev->CreateDescriptorHeap(&h, IID_PPV_ARGS(&m_srv_heap));
        if (FAILED(hr)) return fail("srv-heap", hr);
    }
    auto make_tex = [&](D3D12_RESOURCE_STATES init, ID3D12Resource** out) -> HRESULT
    {
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = D3D12_HEAP_TYPE_DEFAULT;
        D3D12_RESOURCE_DESC d{};
        d.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;
        d.Width = W;
        d.Height = H;
        d.DepthOrArraySize = 1;
        d.MipLevels = 1;
        d.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        d.SampleDesc.Count = 1;
        d.Layout = D3D12_TEXTURE_LAYOUT_UNKNOWN;
        d.Flags = D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET;
        D3D12_CLEAR_VALUE cv{};
        cv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        cv.Color[3] = 1.0f;
        return dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d, init, &cv, IID_PPV_ARGS(out));
    };
    if (!m_scratch_tex)
    {
        hr = make_tex(D3D12_RESOURCE_STATE_RENDER_TARGET, &m_scratch_tex);
        if (FAILED(hr)) return fail("scratch-tex", hr);
        m_scratch_state = D3D12_RESOURCE_STATE_RENDER_TARGET;
        D3D12_CPU_DESCRIPTOR_HANDLE h = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
        dev->CreateRenderTargetView(m_scratch_tex.Get(), nullptr, h);
        D3D12_SHADER_RESOURCE_VIEW_DESC sv{};
        sv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        sv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        sv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        sv.Texture2D.MipLevels = 1;
        D3D12_CPU_DESCRIPTOR_HANDLE sh = m_srv_heap->GetCPUDescriptorHandleForHeapStart();
        UINT inc = dev->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
        sh.ptr += inc; // slot 1 = scratch (identity)
        dev->CreateShaderResourceView(m_scratch_tex.Get(), &sv, sh);
    }
    if (!m_display_tex)
    {
        hr = make_tex(D3D12_RESOURCE_STATE_COPY_DEST, &m_display_tex);
        if (FAILED(hr)) return fail("display-tex", hr);
        m_display_state = D3D12_RESOURCE_STATE_COPY_DEST;
        D3D12_SHADER_RESOURCE_VIEW_DESC sv{};
        sv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        sv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        // Guest bytes are A8R8G8B8 order in memory; copied raw into an
        // R8G8B8A8 texture the texel components read (R=A,G=R,B=G,A=B).
        // Mapping (1,2,3,0) restores shader (R,G,B,A) = (R,G,B,A) in
        // hardware — no CPU byte-swap of colors.
        sv.Shader4ComponentMapping = D3D12_ENCODE_SHADER_4_COMPONENT_MAPPING(1, 2, 3, 0);
        sv.Texture2D.MipLevels = 1;
        D3D12_CPU_DESCRIPTOR_HANDLE sh = m_srv_heap->GetCPUDescriptorHandleForHeapStart();
        dev->CreateShaderResourceView(m_display_tex.Get(), &sv, sh); // slot 0 = display
    }
    auto make_upload = [&](UINT64 bytes, ID3D12Resource** out, UINT8** cpu, D3D12_GPU_VIRTUAL_ADDRESS* gpu) -> HRESULT
    {
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = D3D12_HEAP_TYPE_UPLOAD;
        D3D12_RESOURCE_DESC d{};
        d.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        d.Width = bytes;
        d.Height = 1;
        d.DepthOrArraySize = 1;
        d.MipLevels = 1;
        d.SampleDesc.Count = 1;
        d.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        HRESULT r = dev->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &d,
                                                 D3D12_RESOURCE_STATE_GENERIC_READ, nullptr, IID_PPV_ARGS(out));
        if (FAILED(r)) return r;
        D3D12_RANGE none{0, 0};
        void* p = nullptr;
        r = (*out)->Map(0, &none, &p);
        if (FAILED(r)) return r;
        *cpu = static_cast<UINT8*>(p);
        *gpu = (*out)->GetGPUVirtualAddress();
        return S_OK;
    };
    if (!m_vtx_upload)
    {
        hr = make_upload(8ull << 20, &m_vtx_upload, &m_vtx_cpu, &m_vtx_gpu);
        if (FAILED(hr)) return fail("vtx-upload", hr);
    }
    if (!m_disp_upload)
    {
        UINT8* dc = nullptr;
        D3D12_GPU_VIRTUAL_ADDRESS dg = 0;
        hr = make_upload(4ull << 20, &m_disp_upload, &dc, &dg);
        if (FAILED(hr)) return fail("disp-upload", hr);
        m_disp_cpu = dc;
    }
    if (!m_fence)
    {
        hr = dev->CreateFence(0, D3D12_FENCE_FLAG_NONE, IID_PPV_ARGS(&m_fence));
        if (FAILED(hr)) return fail("fence", hr);
        m_fence_event = CreateEventEx(nullptr, nullptr, 0, EVENT_ALL_ACCESS);
        if (!m_fence_event) return fail("fence-event", HRESULT_FROM_WIN32(GetLastError()));
    }

    m_slice_ok = true;
    wd("BOOT-SLICE-PSO-OK slice+blit PSOs + 1280x720 scratch/display + upload rings ready\r\n");
    return true;
}

void D3D12GSRender::slice_open_list_if_needed()
{
    if (m_list_open || !m_slice_ok)
        return;
    // Defensive open (flip/end without begin): wait for the previous
    // frame's fence, reset, and clear the scratch RTV so the blit has
    // defined content even when no begin() ran this frame.
    if (m_fence_value > 0 && m_fence->GetCompletedValue() < m_fence_value)
    {
        m_fence->SetEventOnCompletion(m_fence_value, m_fence_event);
        WaitForSingleObject(m_fence_event, INFINITE);
    }
    m_slice_alloc->Reset();
    m_slice_list->Reset(m_slice_alloc.Get(), nullptr);
    m_list_open = true;
    m_up_cursor = 0;
    // A previous flip that failed mid-blit may have left the scratch
    // texture in PIXEL_SHADER_RESOURCE; transition back before clearing.
    barrier(m_slice_list.Get(), m_scratch_tex.Get(), m_scratch_state, D3D12_RESOURCE_STATE_RENDER_TARGET);
    m_scratch_state = D3D12_RESOURCE_STATE_RENDER_TARGET;
    D3D12_CPU_DESCRIPTOR_HANDLE rtv = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
    m_slice_list->OMSetRenderTargets(1, &rtv, FALSE, nullptr);
    const float cc[4] = {
        rsx::method_registers.clear_color_r() / 255.0f,
        rsx::method_registers.clear_color_g() / 255.0f,
        rsx::method_registers.clear_color_b() / 255.0f,
        rsx::method_registers.clear_color_a() / 255.0f,
    };
    m_slice_list->ClearRenderTargetView(rtv, cc, 0, nullptr);
}

void D3D12GSRender::slice_begin_frame()
{
    if (!s_bridge.device)
        return; // nop fallback: no bridge, no slice work
    if (!slice_ensure_resources())
        return; // failure already logged once; retry next frame
    // 1.0.40 LIFETIME FIX + BOOT-LIST-RESET diagnostic: begin() is a
    // draw-clause boundary, NOT a frame boundary. The list is opened
    // ONCE per submission interval (first clause after a flip); later
    // clauses only append draws. Previously every clause Reset the
    // allocator+list (return values IGNORED — post-first-clause
    // Resets return E_FAIL on an open list), cleared the scratch RTV
    // (erasing earlier clauses' pixels), and rewound m_up_cursor to 0
    // (overwriting earlier clauses' upload data before submission).
    // draws_since_execute uses s_real_draws at the last Execute.
    const u64 begin_no = s_begin_count.load();
    const u64 draws_since = s_real_draws.load() - m_draws_at_execute;
    const u64 cursor_entry = m_up_cursor;
    // 1.0.41 LIST-RESET CAP: the RSX thread is the sole writer of these
    // counters (slice_begin_frame runs on the RSX thread). Cap
    // list_open=1 lines at 32 and list_open=0 lines at 64; FAILED(hr)
    // resets always log regardless of cap, so a failure is never hidden.
    static std::atomic<u64> open1_logged{0};
    static std::atomic<u64> open0_logged{0};
    if (m_list_open)
    {
        if (open1_logged++ < 32)
        wd("BOOT-LIST-RESET begin=%llu list_open=1 alloc_hr=NA list_hr=NA draws_since_execute=%llu upload_cursor=%llu\r\n",
           (unsigned long long)begin_no, (unsigned long long)draws_since, (unsigned long long)cursor_entry);
        return; // append-only: no reset, no clear, no cursor rewind
    }
    // Wait for the previous frame's GPU work before resetting the
    // allocator (1-frame latency; the wait covers draw time, not
    // vsync — Present is async to the fence signal).
    if (m_fence_value > 0 && m_fence->GetCompletedValue() < m_fence_value)
    {
        m_fence->SetEventOnCompletion(m_fence_value, m_fence_event);
        WaitForSingleObject(m_fence_event, INFINITE);
    }
    HRESULT alloc_hr = m_slice_alloc->Reset();
    HRESULT list_hr = m_slice_list->Reset(m_slice_alloc.Get(), nullptr);
    if (open0_logged++ < 64 || FAILED(alloc_hr) || FAILED(list_hr))
    wd("BOOT-LIST-RESET begin=%llu list_open=0 alloc_hr=0x%08lX list_hr=0x%08lX draws_since_execute=%llu upload_cursor=%llu\r\n",
       (unsigned long long)begin_no, (unsigned long)alloc_hr, (unsigned long)list_hr,
       (unsigned long long)draws_since, (unsigned long long)cursor_entry);
    if (FAILED(alloc_hr) || FAILED(list_hr))
        return; // do NOT mark open: the defensive open in draw/present retries
    m_list_open = true;
    m_up_cursor = 0;
    barrier(m_slice_list.Get(), m_scratch_tex.Get(), m_scratch_state, D3D12_RESOURCE_STATE_RENDER_TARGET);
    m_scratch_state = D3D12_RESOURCE_STATE_RENDER_TARGET;
    D3D12_CPU_DESCRIPTOR_HANDLE rtv = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
    m_slice_list->OMSetRenderTargets(1, &rtv, FALSE, nullptr);
    const float cc[4] = {
        rsx::method_registers.clear_color_r() / 255.0f,
        rsx::method_registers.clear_color_g() / 255.0f,
        rsx::method_registers.clear_color_b() / 255.0f,
        rsx::method_registers.clear_color_a() / 255.0f,
    };
    m_slice_list->ClearRenderTargetView(rtv, cc, 0, nullptr);
}

bool D3D12GSRender::slice_try_real_draw()
{
    if (!m_slice_ok)
        return false;

    const auto& dc = rsx::method_registers.current_draw_clause;
    if (dc.is_immediate_draw)
    {
        slice_note_skip(kSkipImmediate);
        return false;
    }

    // Backend-agnostic vertex analyse (same entry VK/GL use).
    rsx::vertex_input_layout layout;
    GRAPH_frontend().analyse_inputs_interleaved(layout, current_vp_metadata);
    if (!layout.validate() || layout.interleaved_blocks.empty())
    {
        slice_note_skip(kSkipLayout);
        return false;
    }

    // Block holding attribute 0 (POS); fall back to block 0 if the
    // layout does not tag it (should not happen when validate() passes).
    const rsx::interleaved_range_info* blk = nullptr;
    for (const auto* b : layout.interleaved_blocks)
    {
        for (const auto& loc : b->locations)
        {
            if (loc.index == 0)
            {
                blk = b;
                break;
            }
        }
        if (blk)
            break;
    }
    if (!blk)
        blk = layout.interleaved_blocks[0];
    if (blk->single_vertex)
    {
        slice_note_skip(kSkipSingleVertex);
        return false;
    }

    const auto& arr0 = rsx::method_registers.vertex_arrays_info[0];
    if (arr0.size() == 0)
    {
        slice_note_skip(kSkipNoPos);
        return false;
    }
    // In-block byte offset of POS: block base_offset is the masked
    // register offset (analyse groups by diff <= stride, so this
    // difference is within the vertex stride for a true member).
    const u32 arr0_base = arr0.offset() & 0x7fffffff;
    if (arr0_base < blk->base_offset)
    {
        slice_note_skip(kSkipOffset);
        return false;
    }
    const u32 in_block = arr0_base - blk->base_offset;
    u32 stride = blk->attribute_stride ? blk->attribute_stride : arr0.stride();
    if (stride == 0 || in_block >= stride)
    {
        slice_note_skip(kSkipOffset);
        return false;
    }

    // POS type conversion (guest BE -> host LE on upload).
    const auto ptype = arr0.type();
    const u32 comps = arr0.size();
    if (comps == 0 || comps > 4 ||
        (ptype != rsx::vertex_base_type::f && ptype != rsx::vertex_base_type::s1 &&
         ptype != rsx::vertex_base_type::ub))
    {
        slice_note_skip(kSkipType);
        return false;
    }
    const u32 comp_bytes = (ptype == rsx::vertex_base_type::f) ? 4 : (ptype == rsx::vertex_base_type::s1) ? 2 : 1;

    slice_open_list_if_needed();
    if (!m_list_open)
        return false;

    // 1.0.40 VP-DIAG stats: converted-position range + first positions
    // + raw W (component 3, when present). Filled by upload_pos_range.
    float pos_min[3] = {1e30f, 1e30f, 1e30f};
    float pos_max[3] = {-1e30f, -1e30f, -1e30f};
    float pos_first[4][3] = {};
    float pos_first_w[4] = {};
    u32 pos_first_count = 0;

    auto upload_pos_range = [&](u32 first_vertex, u32 vertex_count, UINT64* out_gpu_off) -> bool
    {
        const UINT64 need = static_cast<UINT64>(vertex_count) * 12ull;
        if (vertex_count == 0 || vertex_count > 65536 || m_up_cursor + need > (8ull << 20))
        {
            slice_note_skip(kSkipOverflow);
            return false;
        }
        const u32 guest_bytes = vertex_count * stride;
        const u32 guest_addr = blk->real_offset_address + in_block + first_vertex * stride;
        if (!vm::check_addr(guest_addr, vm::page_readable, guest_bytes))
        {
            slice_note_skip(kSkipUnmapped);
            return false;
        }
        const u8* src = vm::_ptr<const u8>(guest_addr);
        float* dst = reinterpret_cast<float*>(m_vtx_cpu + m_up_cursor);
        for (u32 v = 0; v < vertex_count; ++v)
        {
            const u8* p = src + static_cast<size_t>(v) * stride;
            float xyz[3] = {0.0f, 0.0f, 0.0f};
            for (u32 c = 0; c < comps && c < 3; ++c)
            {
                if (ptype == rsx::vertex_base_type::f)
                {
                    u32 bits = 0;
                    std::memcpy(&bits, p + c * 4, 4);
                    bits = bswap32(bits);
                    std::memcpy(&xyz[c], &bits, 4);
                }
                else if (ptype == rsx::vertex_base_type::s1)
                {
                    u16 bits = 0;
                    std::memcpy(&bits, p + c * 2, 2);
                    const auto sv = static_cast<s16>(bswap16(bits));
                    xyz[c] = sv / 32767.0f;
                }
                else // ub (UNORM8)
                {
                    xyz[c] = p[c] / 255.0f;
                }
            }
            for (u32 c = 0; c < 3; ++c)
            {
                if (xyz[c] < pos_min[c]) pos_min[c] = xyz[c];
                if (xyz[c] > pos_max[c]) pos_max[c] = xyz[c];
            }
            if (v < 4)
            {
                pos_first[v][0] = xyz[0];
                pos_first[v][1] = xyz[1];
                pos_first[v][2] = xyz[2];
                pos_first_count = v + 1;
                if (comps == 4)
                {
                    // Component 3 sits at 3 * comp_bytes within the vertex.
                    const u8* pw = p + 3 * comp_bytes;
                    if (ptype == rsx::vertex_base_type::f)
                    {
                        u32 bits = 0;
                        std::memcpy(&bits, pw, 4);
                        bits = bswap32(bits);
                        std::memcpy(&pos_first_w[v], &bits, 4);
                    }
                    else if (ptype == rsx::vertex_base_type::s1)
                    {
                        u16 bits = 0;
                        std::memcpy(&bits, pw, 2);
                        pos_first_w[v] = static_cast<s16>(bswap16(bits)) / 32767.0f;
                    }
                    else // ub
                    {
                        pos_first_w[v] = pw[0] / 255.0f;
                    }
                }
            }
            dst[v * 3 + 0] = xyz[0];
            dst[v * 3 + 1] = xyz[1];
            dst[v * 3 + 2] = xyz[2];
        }
        *out_gpu_off = m_vtx_gpu + m_up_cursor;
        m_up_cursor += need;
        return true;
    };

    const TopoMap topo = map_topo(dc.primitive);
    ID3D12PipelineState* pso = nullptr;
    if (topo.type == D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE)
        pso = m_slice_pso_tri.Get();
    else if (topo.type == D3D12_PRIMITIVE_TOPOLOGY_TYPE_LINE)
        pso = m_slice_pso_line.Get();
    else
        pso = m_slice_pso_point.Get();

    auto* list = m_slice_list.Get();
    list->SetGraphicsRootSignature(m_slice_rs.Get());
    list->SetPipelineState(pso);
    list->IASetPrimitiveTopology(topo.topo);
    D3D12_CPU_DESCRIPTOR_HANDLE rtv = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
    list->OMSetRenderTargets(1, &rtv, FALSE, nullptr);

    // 1.0.39: the scratch draws had no viewport/scissor (a freshly Reset
    // command list carries none, and slice_present only sets them for the
    // blit AFTER these draws). Without raster state the draws rasterize
    // zero pixels and the scratch stays cleared black. Set both from the
    // scratch texture itself, before any Draw* call in this function.
    const auto scratch_desc = m_scratch_tex->GetDesc();
    D3D12_VIEWPORT slice_vp{};
    slice_vp.TopLeftX = 0.0f;
    slice_vp.TopLeftY = 0.0f;
    slice_vp.Width = static_cast<float>(scratch_desc.Width);
    slice_vp.Height = static_cast<float>(scratch_desc.Height);
    slice_vp.MinDepth = 0.0f;
    slice_vp.MaxDepth = 1.0f;
    list->RSSetViewports(1, &slice_vp);
    D3D12_RECT slice_sc{};
    slice_sc.left = 0;
    slice_sc.top = 0;
    slice_sc.right = static_cast<LONG>(scratch_desc.Width);
    slice_sc.bottom = static_cast<LONG>(scratch_desc.Height);
    list->RSSetScissorRects(1, &slice_sc);

    if (dc.command == rsx::draw_command::indexed)
    {
        const auto span = GRAPH_frontend().get_raw_index_array(dc);
        const u32 elems = dc.get_elements_count();
        if (elems == 0 || span.size_bytes() < elems)
        {
            slice_note_skip(kSkipLayout);
            return false;
        }
        const u32 tsize = static_cast<u32>(span.size_bytes()) / elems; // 2 or 4
        if (tsize != 2 && tsize != 4)
        {
            slice_note_skip(kSkipLayout);
            return false;
        }
        // Read + BE->LE swap indices; find max vertex index.
        const u8* raw = reinterpret_cast<const u8*>(span.data());
        u32 max_idx = 0;
        const UINT64 idx_need = static_cast<UINT64>(elems) * tsize;
        const UINT64 idx_off = (m_up_cursor + 3ull) & ~3ull;
        if (idx_off + idx_need > (8ull << 20))
        {
            slice_note_skip(kSkipOverflow);
            return false;
        }
        u8* idx_dst = m_vtx_cpu + idx_off;
        for (u32 i = 0; i < elems; ++i)
        {
            u32 v = 0;
            if (tsize == 2)
            {
                u16 bits = 0;
                std::memcpy(&bits, raw + i * 2, 2);
                v = bswap16(bits);
                std::memcpy(idx_dst + i * 2, &v, 2);
            }
            else
            {
                u32 bits = 0;
                std::memcpy(&bits, raw + i * 4, 4);
                v = bswap32(bits);
                std::memcpy(idx_dst + i * 4, &v, 4);
            }
            if (v > max_idx)
                max_idx = v;
        }
        m_up_cursor = idx_off + idx_need;
        // Upload vertices [0, max_idx] (indices are absolute).
        UINT64 vb_off = 0;
        if (!upload_pos_range(0, max_idx + 1, &vb_off))
            return false;
        D3D12_VERTEX_BUFFER_VIEW vbv{};
        vbv.BufferLocation = vb_off;
        vbv.SizeInBytes = (max_idx + 1) * 12u;
        vbv.StrideInBytes = 12;
        list->IASetVertexBuffers(0, 1, &vbv);
        D3D12_INDEX_BUFFER_VIEW ibv{};
        ibv.BufferLocation = m_vtx_gpu + idx_off;
        ibv.SizeInBytes = static_cast<UINT>(idx_need);
        ibv.Format = (tsize == 2) ? DXGI_FORMAT_R16_UINT : DXGI_FORMAT_R32_UINT;
        list->IASetIndexBuffer(&ibv);
        list->DrawIndexedInstanced(elems, 1, 0, 0, 0);
    }
    else
    {
        // Array draw: one upload covering the subrange union, one
        // DrawInstanced per subrange.
        const auto& subs = dc.get_subranges();
        if (subs.empty())
        {
            slice_note_skip(kSkipLayout);
            return false;
        }
        u32 lo = UINT32_MAX, hi = 0;
        for (const auto& s : subs)
        {
            if (s.count == 0)
                continue;
            if (s.first < lo) lo = s.first;
            if (s.first + s.count > hi) hi = s.first + s.count;
        }
        if (lo == UINT32_MAX || hi <= lo)
        {
            slice_note_skip(kSkipLayout);
            return false;
        }
        UINT64 vb_off = 0;
        if (!upload_pos_range(lo, hi - lo, &vb_off))
            return false;
        D3D12_VERTEX_BUFFER_VIEW vbv{};
        vbv.BufferLocation = vb_off;
        vbv.SizeInBytes = (hi - lo) * 12u;
        vbv.StrideInBytes = 12;
        list->IASetVertexBuffers(0, 1, &vbv);
        for (const auto& s : subs)
        {
            if (s.count == 0)
                continue;
            list->DrawInstanced(s.count, 1, s.first - lo, 0);
        }
    }

    // 1.0.40 VP-DIAG: first occurrence per VP hash + first 3 draws
    // overall. Tests the attr0-as-POS assumption: ref bit 0 clear
    // means input 0 is not referenced by the guest vertex program.
    // p0/p1 are the first two converted attr0 vertices (n = count
    // valid; p1 is zeros when n == 1); mn/mx cover the whole uploaded
    // range; w0/w1 are raw component 3 (only when comps == 4).
    if (current_vp_metadata.ucode_length != 0)
    {
        const u64 vp_hash_diag = static_cast<u64>(
            program_hash_util::vertex_program_utils::get_vertex_program_ucode_hash(current_vertex_program));
        const bool vp_first_seen = m_vp_logged.insert(vp_hash_diag).second;
        if (vp_first_seen || m_vp_log_draws < 3)
        {
            ++m_vp_log_draws;
            if (comps == 4)
            {
                wd("BOOT-VP-DIAG vp=0x%016llX ref=0x%04X ulen=%u out=0x%08X t=%d c=%u st=%u ib=%u n=%u p0=(%.3g,%.3g,%.3g) p1=(%.3g,%.3g,%.3g) mn=(%.3g,%.3g,%.3g) mx=(%.3g,%.3g,%.3g) w0=%.3g w1=%.3g\r\n",
                   (unsigned long long)vp_hash_diag, (unsigned)current_vp_metadata.referenced_inputs_mask,
                   (unsigned)current_vp_metadata.ucode_length, (unsigned)current_vertex_program.output_mask,
                   (int)ptype, (unsigned)comps, (unsigned)stride, (unsigned)in_block, (unsigned)pos_first_count,
                   pos_first[0][0], pos_first[0][1], pos_first[0][2],
                   pos_first[1][0], pos_first[1][1], pos_first[1][2],
                   pos_min[0], pos_min[1], pos_min[2], pos_max[0], pos_max[1], pos_max[2],
                   pos_first_w[0], pos_first_w[1]);
            }
            else
            {
                wd("BOOT-VP-DIAG vp=0x%016llX ref=0x%04X ulen=%u out=0x%08X t=%d c=%u st=%u ib=%u n=%u p0=(%.3g,%.3g,%.3g) p1=(%.3g,%.3g,%.3g) mn=(%.3g,%.3g,%.3g) mx=(%.3g,%.3g,%.3g) w=NA\r\n",
                   (unsigned long long)vp_hash_diag, (unsigned)current_vp_metadata.referenced_inputs_mask,
                   (unsigned)current_vp_metadata.ucode_length, (unsigned)current_vertex_program.output_mask,
                   (int)ptype, (unsigned)comps, (unsigned)stride, (unsigned)in_block, (unsigned)pos_first_count,
                   pos_first[0][0], pos_first[0][1], pos_first[0][2],
                   pos_first[1][0], pos_first[1][1], pos_first[1][2],
                   pos_min[0], pos_min[1], pos_min[2], pos_max[0], pos_max[1], pos_max[2]);
            }
        }
    }

    s_real_draws.fetch_add(1);
    return true;
}

void D3D12GSRender::slice_present(const rsx::display_flip_info_t& info)
{
    // 1.0.38 DIAGNOSTIC ONLY (single place to revert): always present the
    // scratch RTV, ignoring the guest display buffer nonzero test below.
    // Tests whether the real draws are hidden behind a stale-black guest
    // display buffer with one nonzero word. See BOOT-DIAG-FORCE-SCRATCH.
    static const bool kForceScratchDiag = true;
    {
        static bool force_scratch_logged = false;
        if (kForceScratchDiag && !force_scratch_logged)
        {
            force_scratch_logged = true;
            wd("BOOT-DIAG-FORCE-SCRATCH active: scratch RTV always presented, guest display buffer ignored\r\n");
        }
    }
    {
        static bool pixel_ndc_logged = false;
        if (!pixel_ndc_logged)
        {
            pixel_ndc_logged = true;
            wd("BOOT-DIAG-PIXEL-NDC active 1280x720 dual-guard: pixel-space draws map to NDC, pre-normalized pass through\r\n");
        }
    }
    // 1.0.42 ORDERING: hand Present ownership to RSX BEFORE the first
    // RSX Present, so the main thread's test-pattern loop cannot issue
    // a concurrent Present on the bridge queue during the first RSX
    // flip. (Moved from the post-Present success branch below; the
    // once-gate is unchanged, so this fires on the first slice_present
    // call. If that first Present were to fail, the host pattern would
    // not resume - Present has succeeded on every RSX flip since Step 4.)
    {
        auto* owns_top = s_bridge.rsx_owns_swapchain;
        if (owns_top && !owns_top->load(std::memory_order_acquire))
        {
            owns_top->store(true, std::memory_order_release);
            if (!m_owns_logged)
            {
                m_owns_logged = true;
                wd("BOOT-RSX-OWNS-SWAPCHAIN ms=%lld (first valid RSX flip blitted+presented; host test-pattern Present stops)\r\n",
                   watchdog_ms_since_boot());
            }
        }
    }
    ID3D12Device* dev = s_bridge.device;
    ID3D12CommandQueue* queue = s_bridge.queue;
    IDXGISwapChain3* swap = s_bridge.swapchain;
    if (!dev || !queue || !swap || !m_slice_ok)
        return;
    slice_open_list_if_needed();
    if (!m_list_open)
        return;
    auto* list = m_slice_list.Get();

    // ---- Slice 1 display-buffer upload ----
    // Tree-correct lookup (GLPresent.cpp:173-217 precedent): the
    // thread's display_buffers[] are RsxDisplayInfo { offset, pitch,
    // width, height } (be_t fields); the guest address is the LOCAL
    // (RSX memory) mapping of the offset. Display buffers are read
    // linearly by the display hardware — no tile check (GLPresent
    // does none either). Only the exact 1280x720 mode feeds the
    // fixed display texture; any other mode falls back to the scratch
    // path and is reported once (BOOT-SLICE-DISPLAY) so the next
    // build can size the texture to the real mode.
    bool have_display = false;
    const UINT W = s_bridge.width ? s_bridge.width : 1280;
    const UINT H = s_bridge.height ? s_bridge.height : 720;
    const UINT64 disp_bytes = static_cast<UINT64>(W) * H * 4ull;
    if (info.buffer < display_buffers_count)
    {
        const auto& db = display_buffers[info.buffer];
        const u32 bw = db.width, bh = db.height, bp = db.pitch;
        static bool disp_dims_logged = false;
        if (!disp_dims_logged)
        {
            disp_dims_logged = true;
            wd("BOOT-SLICE-DISPLAY buffer=%u width=%u height=%u pitch=%u offset=0x%X\r\n",
               info.buffer, bw, bh, bp, static_cast<u32>(db.offset));
        }
        const u32 addr = rsx::get_address(db.offset, CELL_GCM_LOCATION_LOCAL);
        if (bw == W && bh == H && bp >= W * 4 &&
            vm::check_addr(addr, vm::page_readable, static_cast<u32>(disp_bytes)))
        {
            const u8* px = vm::_ptr<const u8>(addr);
            bool nonzero = false;
            for (u32 y = 0; y < H && !nonzero; ++y)
            {
                const u32* row = reinterpret_cast<const u32*>(px + static_cast<size_t>(y) * bp);
                for (u32 x = 0; x < W; ++x)
                {
                    if (row[x] != 0)
                    {
                        nonzero = true;
                        break;
                    }
                }
            }
            if (nonzero)
            {
                // Guest bytes copied row by row (pitch-aware); the SRV
                // swizzle mapping (1,2,3,0) fixes the channel order
                // in hardware — no CPU byte-swap of colors.
                for (u32 y = 0; y < H; ++y)
                    std::memcpy(m_disp_cpu + static_cast<size_t>(y) * W * 4,
                                px + static_cast<size_t>(y) * bp, W * 4);
                barrier(list, m_display_tex.Get(), m_display_state, D3D12_RESOURCE_STATE_COPY_DEST);
                m_display_state = D3D12_RESOURCE_STATE_COPY_DEST;
                D3D12_TEXTURE_COPY_LOCATION src{};
                src.pResource = m_disp_upload.Get();
                src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
                src.PlacedFootprint.Offset = 0;
                src.PlacedFootprint.Footprint.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
                src.PlacedFootprint.Footprint.Width = W;
                src.PlacedFootprint.Footprint.Height = H;
                src.PlacedFootprint.Footprint.Depth = 1;
                src.PlacedFootprint.Footprint.RowPitch = W * 4;
                D3D12_TEXTURE_COPY_LOCATION dst{};
                dst.pResource = m_display_tex.Get();
                dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
                dst.SubresourceIndex = 0;
                list->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
                have_display = true;
            }
        }
        // Any other mode (non-720p, short pitch, unmapped) falls back
        // to the scratch path; BOOT-SLICE-DISPLAY above names the mode.
    }
    // 1.0.38 diagnostic override (see kForceScratchDiag above).
    if (kForceScratchDiag)
        have_display = false;

    // ---- Swapchain backbuffer RTVs (once) ----
    if (!m_swap_rtvs_made)
    {
        UINT inc = dev->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_RTV);
        D3D12_CPU_DESCRIPTOR_HANDLE h = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
        for (UINT i = 0; i < 2; ++i)
        {
            Microsoft::WRL::ComPtr<ID3D12Resource> bb;
            if (FAILED(swap->GetBuffer(i, IID_PPV_ARGS(&bb))))
                return;
            D3D12_CPU_DESCRIPTOR_HANDLE slot = h;
            slot.ptr += inc * (1 + i);
            dev->CreateRenderTargetView(bb.Get(), nullptr, slot);
        }
        m_swap_rtvs_made = true;
    }
    const UINT bb_index = swap->GetCurrentBackBufferIndex();
    Microsoft::WRL::ComPtr<ID3D12Resource> bb;
    if (FAILED(swap->GetBuffer(bb_index, IID_PPV_ARGS(&bb))))
        return;
    D3D12_RESOURCE_DESC bb_desc = bb->GetDesc();

    // 1.0.42: present-time magenta clear REMOVED (was the 1.0.40
    // diagnostic) - guest draws recorded during the frame now reach
    // the screen. Force-scratch stays on.
    {
        static bool magenta_removed_logged = false;
        if (!magenta_removed_logged)
        {
            magenta_removed_logged = true;
            wd("BOOT-DIAG-MAGENTA-REMOVED active: present-time magenta clear removed, guest draws reach the screen\r\n");
        }
    }

    // ---- Blit: scratch (or display) -> backbuffer ----
    barrier(list, m_scratch_tex.Get(), m_scratch_state, D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE);
    if (have_display)
        barrier(list, m_display_tex.Get(), m_display_state, D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE);
    barrier(list, bb.Get(), D3D12_RESOURCE_STATE_PRESENT, D3D12_RESOURCE_STATE_RENDER_TARGET);

    UINT rtv_inc = dev->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_RTV);
    D3D12_CPU_DESCRIPTOR_HANDLE bb_rtv = m_rtv_heap->GetCPUDescriptorHandleForHeapStart();
    bb_rtv.ptr += rtv_inc * (1 + bb_index);
    list->OMSetRenderTargets(1, &bb_rtv, FALSE, nullptr);
    D3D12_VIEWPORT vp{};
    vp.Width = static_cast<float>(bb_desc.Width);
    vp.Height = static_cast<float>(bb_desc.Height);
    vp.MaxDepth = 1.0f;
    list->RSSetViewports(1, &vp);
    D3D12_RECT sc{0, 0, static_cast<LONG>(bb_desc.Width), static_cast<LONG>(bb_desc.Height)};
    list->RSSetScissorRects(1, &sc);
    ID3D12DescriptorHeap* heaps[] = {m_srv_heap.Get()};
    list->SetDescriptorHeaps(1, heaps);
    list->SetGraphicsRootSignature(m_blit_rs.Get());
    list->SetPipelineState(m_blit_pso.Get());
    D3D12_GPU_DESCRIPTOR_HANDLE srv = m_srv_heap->GetGPUDescriptorHandleForHeapStart();
    if (!have_display)
    {
        UINT inc = dev->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
        srv.ptr += inc; // slot 1 = scratch (identity)
    }
    list->SetGraphicsRootDescriptorTable(0, srv);
    list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    list->DrawInstanced(3, 1, 0, 0);

    barrier(list, bb.Get(), D3D12_RESOURCE_STATE_RENDER_TARGET, D3D12_RESOURCE_STATE_PRESENT);
    barrier(list, m_scratch_tex.Get(), D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_RENDER_TARGET);
    m_scratch_state = D3D12_RESOURCE_STATE_RENDER_TARGET;
    if (have_display)
    {
        barrier(list, m_display_tex.Get(), D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_COPY_DEST);
        m_display_state = D3D12_RESOURCE_STATE_COPY_DEST;
    }

    HRESULT hr = list->Close();
    if (FAILED(hr))
        return;
    m_list_open = false;
    ID3D12CommandList* lists[] = {list};
    queue->ExecuteCommandLists(1, lists);
    m_draws_at_execute = s_real_draws.load(); // 1.0.40: draws_since_execute base
    // 1.0.42 ORDERING: fence always tracks ExecuteCommandLists, even if
    // Present below fails - the allocator is in flight once executed.
    ++m_fence_value;
    queue->Signal(m_fence.Get(), m_fence_value);
    hr = swap->Present(1, 0);
}

void D3D12GSRender::flip(const rsx::display_flip_info_t& info)
{
    s_flip_count.fetch_add(1);
    // 1.0.36: Slice 1 blit (count-only when the bridge is absent or
    // Slice resources failed; nop fallback preserved).
    if (s_bridge.device)
    {
        if (!m_slice_ok)
            slice_ensure_resources(); // retry init; flip stays count-only until it succeeds
        if (m_slice_ok)
            slice_present(info);
    }
    GSRender::flip(info);
}

void D3D12GSRender::end()
{
    s_end_count.fetch_add(1);

    // 1.0.37 GUARD — tree-verified against Emu/RSX/NV47/FW/draw_call.hpp
    // and draw_call.inc.h (NOT Argon's sketch verbatim; divergences are
    // tree-mandated and listed below). The 1.0.36 RSX thread died in
    // draw_clause::get_range() (:303, ensure(current_range_index <
    // draw_command_ranges.size())) before flip 1. Two trip points,
    // both covered here, BEFORE any range-touching call (the slice's
    // get_raw_index_array -> min_index()/get_elements_count() ->
    // get_range(), and get_subranges()):
    //  (a) Empty clause: empty() is true when draw_command_ranges is
    //      empty (or, for inlined_array, inline_vertex_array is
    //      empty); every range helper's ensure throws on it.
    //  (b) Stale iterator: nv4097.cpp:531 compile() — the ONLY
    //      compile() caller, guarded by !empty() and run immediately
    //      before RSX->end() — sets current_range_index = ~0u, and
    //      nothing calls begin() between compile() and our end(), so
    //      get_range would throw even on a NON-empty clause (~0u <
    //      size is false). begin() resets the index to 0.
    // Divergences from Argon's sketch:
    //  - No clause.is_end() exists in this tree. No post-begin
    //    re-check is possible or needed: begin() changes no ranges,
    //    so !empty() at entry IS get_range's precondition at index 0;
    //    every other candidate check (get_elements_count(),
    //    pass_count(), is_single_draw()) itself throws on empty
    //    ranges and cannot serve as a guard. draw_command_ranges is
    //    a PRIVATE member (draw_call.hpp:22, public: starts at :71),
    //    so it cannot be read directly either.
    //  - compile() is NOT re-called here: nv4097 already compiled the
    //    clause, and re-calling it would only reset the index to ~0u
    //    again (which begin() below would then undo).
    //  - Accessor is rsx::method_registers.current_draw_clause
    //    (already used by slice_try_real_draw); enum values are
    //    rsx::draw_command::{none,array,inlined_array,indexed}
    //    (draw_call.inc.h:7).
    // Bracket discipline: there is NO early return in this function.
    // Guard skips only gate the real-draw call; every path flows
    // through the SAME tail (execute_nop_draw + rsx::thread::end()),
    // mirroring the proven RSXThread.cpp:3076-3080 error path.
    // thread::end() runs post_execute_cleanup (ensure index == 0),
    // which the nop loop's next() guarantees. Inlined_array draws
    // are SKIPPED (nop-counted) in this build — their vertices live
    // in inline_vertex_array and get_range does not apply; the
    // inlined vertex path is a follow-up, not 1.0.37.
    // analyse_current_rsx_pipeline() below touches no ranges
    // (RSXThread.cpp:2318-2335: program prefetch only), so it is
    // safe to run on the guard path too; only the slice call is
    // gated, because only it touches ranges.
    auto& clause = rsx::method_registers.current_draw_clause;
    bool clause_ok = true;
    bool inlined_skipped = false; // 1.0.43 (i): set in the inlined_array branch below.
    if (clause.empty())
    {
        slice_note_skip(kSkipEmptyClause);
        clause_ok = false;
    }
    else if (clause.command == rsx::draw_command::inlined_array)
    {
        s_inlined_skips.fetch_add(1);
        inlined_skipped = true;
        slice_note_skip(kSkipInlinedArray);
        clause_ok = false;
    }
    else if (clause.command != rsx::draw_command::array &&
             clause.command != rsx::draw_command::indexed)
    {
        slice_note_skip(kSkipNoCommand);
        clause_ok = false;
    }
    else
    {
        clause.begin();
    }

    // 1.0.36 Slice 2: tree-correct pipeline analyse FIRST (prefetches
    // the current vertex/fragment programs for the draw below).
    analyse_current_rsx_pipeline();

    // Real ucode-hash instrumentation (tree-confirmed API).
    // 1.0.43 (ii): un-sampled VP tracking on ALL paths (analyse runs on the guard
    // path too, so inlined_array draws are tracked despite the skip below).
    // 1.0.43 (i): INLINE-SKIP log (first 16 occurrences + any new-VP occurrence).
    bool vp_is_new = false;
    u64 vp_track_hash = 0;
    if (current_vp_metadata.ucode_length != 0)
    {
        vp_track_hash = static_cast<u64>(
            program_hash_util::vertex_program_utils::get_vertex_program_ucode_hash(current_vertex_program));
        vp_is_new = vp_track(vp_track_hash, static_cast<int>(clause.command));
    }
    if (inlined_skipped)
    {
        const unsigned long long skip_no = s_inlined_skips.load();
        if (skip_no <= 16 || vp_is_new)
            wd("[INLINE-SKIP] seq=%llu vp_hash=0x%016llX count=%llu\r\n",
               skip_no, (unsigned long long)vp_track_hash, skip_no);
    }
    // Skip draws whose prefetched programs are still empty: hashing
    // a default program would collapse them onto one bogus key.
    if (current_vp_metadata.ucode_length != 0 &&
        current_fp_metadata.program_ucode_length != 0)
    {
        const u64 vp_hash = static_cast<u64>(
            program_hash_util::vertex_program_utils::get_vertex_program_ucode_hash(current_vertex_program));
        const u64 fp_hash = static_cast<u64>(
            program_hash_util::fragment_program_utils::get_fragment_program_ucode_hash(current_fragment_program));
        const auto key = std::make_pair(vp_hash, fp_hash);
        if (s_seen_pairs.insert(key).second)
        {
            s_shader_distinct.fetch_add(1);
            if (cache_lookup(vp_hash, fp_hash))
            {
                s_shader_hits.fetch_add(1);
            }
            else
            {
                // First sight of a missing pair: record in the ring.
                const u64 ordinal = s_miss_next.fetch_add(1);
                s_miss_ring[ordinal % kMissRingSize] = key;
                s_shader_misses.fetch_add(1);
            }
        }
        else if (cache_lookup(vp_hash, fp_hash))
        {
            // Repeat draw of a cached pair: still a HIT, but not a
            // new distinct pair. (Distinct counting and hit counting
            // are separate: distinct counts pairs, hits count draws.)
            s_shader_hits.fetch_add(1);
        }
    }

    // 1.0.36 Slice 2 real draw; the nop seam is kept for thread-state
    // comparability (same as NullGSRender) whether or not the real
    // draw executed. 1.0.37: gated on the clause guard above — a
    // skipped clause never reaches range-touching slice code.
    if (clause_ok && s_bridge.device)
        slice_try_real_draw();
    execute_nop_draw();
    rsx::thread::end();
}

// Free-function accessors for the /ZW host TU (see rsx_counters.h).
std::uint64_t d3d12_rsx_init_count() { return D3D12GSRender::s_init_count.load(); }
std::uint64_t d3d12_rsx_begin_count() { return D3D12GSRender::s_begin_count.load(); }
std::uint64_t d3d12_rsx_end_count() { return D3D12GSRender::s_end_count.load(); }
std::uint64_t d3d12_rsx_flip_count() { return D3D12GSRender::s_flip_count.load(); }
std::uint64_t d3d12_rsx_shader_distinct() { return D3D12GSRender::s_shader_distinct.load(); }
std::uint64_t d3d12_rsx_shader_hits() { return D3D12GSRender::s_shader_hits.load(); }
std::uint64_t d3d12_rsx_shader_misses() { return D3D12GSRender::s_shader_misses.load(); }
std::uint64_t d3d12_rsx_shader_cache_entries() { return D3D12GSRender::s_cache_entries.load(); }
std::uint64_t d3d12_rsx_rtt_bytes() { return D3D12GSRender::s_rtt_bytes.load(); }
std::uint64_t d3d12_rsx_texture_bytes() { return D3D12GSRender::s_texture_bytes.load(); }
std::uint64_t d3d12_rsx_upload_bytes() { return D3D12GSRender::s_upload_bytes.load(); }
std::uint64_t d3d12_rsx_pso_bytes() { return D3D12GSRender::s_pso_bytes.load(); }
std::uint64_t d3d12_rsx_real_draws() { return D3D12GSRender::s_real_draws.load(); }
std::uint64_t d3d12_rsx_real_skips() { return D3D12GSRender::s_real_skips.load(); }
bool d3d12_rsx_shader_miss_at(std::uint64_t ordinal, std::uint64_t* vp, std::uint64_t* fp)
{
    return D3D12GSRender::miss_at(ordinal, vp, fp);
}
std::string d3d12_rsx_shader_cache_path()
{
    return D3D12GSRender::cache_path();
}

void D3D12GSRender::on_exit()
{
    {
        char wbuf[256];
        std::snprintf(wbuf, sizeof(wbuf), "BOOT-RSX-THREAD-STOP ms=%lld (RSX thread ending; base on_exit follows)\r\n", watchdog_ms_since_boot());
        watchdog_append(wbuf);
    }
    GSRender::on_exit();
}

std::uint64_t d3d12_rsx_inlined_skips() { return s_inlined_skips.load(); } // 1.0.43 (i)